local DreamAdventuresProgressRewardsDialog = Class("DreamAdventuresProgressRewardsDialog")

--region lifecycle
function DreamAdventuresProgressRewardsDialog:__init()
    self._viewType = DreamAdventuresConstants.ScheduleRewardPopupType.PERSONAL
    self._rewardsData = {}

end
function DreamAdventuresProgressRewardsDialog:__delete()
    self._rewardsData = nil
    self._viewType = nil
end

function DreamAdventuresProgressRewardsDialog:Awake()
end

function DreamAdventuresProgressRewardsDialog:Start()

end

function DreamAdventuresProgressRewardsDialog:OnInitialize()
    self:InitHandler()
    self:InitData()
    self:RefreshUI()
end

function DreamAdventuresProgressRewardsDialog:OnFinalize()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function DreamAdventuresProgressRewardsDialog:InitHandler()
    SetButtonAction(self.BtnClose, Bind(self,self.BtnCloseOnClickHandler))
    SetButtonAction(self.BtnClose1, Bind(self,self.BtnCloseOnClickHandler))
    SetButtonAction(self.BtnGet, Bind(self,self.BtnGetOnClickHandler))
end

function DreamAdventuresProgressRewardsDialog:InitData()
    local param = self.controller.Argument.parameters
    self:SetViewType(param.type)
    self:InitRewardsData()
end

function DreamAdventuresProgressRewardsDialog:InitRewardsData()
    local viewType = self:GetViewType()
    local rewardsData = {}
    if viewType == DreamAdventuresConstants.ScheduleRewardPopupType.PERSONAL then
        rewardsData = clone(DreamAdventuresMgr:GetPersonalRewardsList())
        local point = DreamAdventuresMgr:GetSelfWinePress()
        local ids = DreamAdventuresMgr:GetSelfWineRewardIds()
        for _, v in ipairs(rewardsData) do
            if point >= checkInt(v.point) then
                if ids[tostring(v.id)] then
                    v.status = DreamAdventuresConstants.ScheduleRewardStatus.FINISHED
                else
                    v.status = DreamAdventuresConstants.ScheduleRewardStatus.GET
                end
            else
                v.status = DreamAdventuresConstants.ScheduleRewardStatus.UNFINISHED
            end
        end
    elseif viewType == DreamAdventuresConstants.ScheduleRewardPopupType.SERVER then 
        rewardsData = clone(DreamAdventuresMgr:GetAllRewardsList())
        local point = DreamAdventuresMgr:GetAllWinePress()
        local ids = DreamAdventuresMgr:GetAllWineRewardIds()
        for _, v in ipairs(rewardsData) do
            if point >= checkInt(v.point) then
                if ids[tostring(v.id)] then
                    v.status = DreamAdventuresConstants.ScheduleRewardStatus.FINISHED
                else
                    v.status = DreamAdventuresConstants.ScheduleRewardStatus.GET
                end
            else
                v.status = DreamAdventuresConstants.ScheduleRewardStatus.UNFINISHED
            end
        end
    end
    
    table.sort(rewardsData, function(a, b)
        if a.status ~= b.status then
            return a.status < b.status
        else
            return checkInt(a.point) < checkInt(b.point) 
        end
    end)
    self:SetRewardsData(rewardsData)
end
--endregion init

--region handler
function DreamAdventuresProgressRewardsDialog:BtnCloseOnClickHandler()
    UIModule.BackDialog()
end

---一键领取
function DreamAdventuresProgressRewardsDialog:BtnGetOnClickHandler()
    local rewardsData = self:GetRewardsData()
    local canDraw = false
    for i, v in ipairs(rewardsData) do
        if v.status == DreamAdventuresConstants.ScheduleRewardStatus.GET then
            canDraw = true
            break
        end
    end
    if not canDraw then
        GameUtils.Toast(localize('暂无可领取的奖励'))
        return
    end
    self:DrawRewards(0)
end

---列表刷新
function DreamAdventuresProgressRewardsDialog:OnGetItemByIndex(listView, index)
    local luaIndex = index + 1
    local cellData = self:GetRewardsData()[luaIndex]
    local cell = listView:NewListViewItem("Cell")
    local scr = CfUtils.GetLuaScr(cell, "Game.Activity.DreamAdventures.DreamAdventuresRewardsCell")
    scr:RefreshCell(cellData, self:GetViewType(), luaIndex, Bind(self, self.CellOnClickHandler))
    --if luaIndex <= listView.DisplayItemCount then
    --    CfUtils.PlayDelayShowAnimation(cell, index)
    --end
    return cell
end

---cell领取按钮点击回调
function DreamAdventuresProgressRewardsDialog:CellOnClickHandler(index)
    local rewardsData = self:GetRewardsData()
    local id = rewardsData[index].id
    self:DrawRewards(id)
end

function DreamAdventuresProgressRewardsDialog:DrawRewardsResponseHandler(request, response)
    if checkNumber(response.errCode) ~= 0 then return end

    local jsonData = response.data
    local rewards = checkTable(jsonData.rewards)
    if #rewards > 0 then
        GoodsUtils.DrawRewards(rewards)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
    end
    
    local viewType = self:GetViewType()
    if viewType == DreamAdventuresConstants.ScheduleRewardPopupType.PERSONAL then
        DreamAdventuresMgr:SetSelfWineRewardIds(jsonData.selfWineRewardIds)
    elseif viewType == DreamAdventuresConstants.ScheduleRewardPopupType.SERVER then
        DreamAdventuresMgr:SetAllWineRewardIds(jsonData.allWineRewardIds)
    end
    self:InitRewardsData()
    self:RefreshUI()
    Events.Broadcast(Constants.EventNames.DreamAdventuresPointRewardsDraw)
end
--endregion handler

--region private
---刷新UI
function DreamAdventuresProgressRewardsDialog:RefreshUI()
    self:RefreshRewardsList()
    self:RefreshProgress()
end

---刷新奖励列表
function DreamAdventuresProgressRewardsDialog:RefreshRewardsList()
    local count = table.count(self:GetRewardsData())
    if not self.RewardLoopView.IsListViewInit then
        self.RewardLoopView:InitListView(count, Bind(self, self.OnGetItemByIndex))
        --self.RewardLoopView:UpdateDisplayItemCount("Cell")
    else
        GameUtils.ReloadData(self.RewardLoopView, count)
    end
end

---刷新进度
function DreamAdventuresProgressRewardsDialog:RefreshProgress()
    local viewType = self:GetViewType()
    if viewType == DreamAdventuresConstants.ScheduleRewardPopupType.PERSONAL then
        CfUtils.SetActive(self.ThatPerson, true)
        CfUtils.SetActive(self.FullServerProgress, false)
        CfUtils.SetActive(self.TextAccumulate, true)
        CfUtils.SetActive(self.TextSchedule, false)
        local point = DreamAdventuresMgr:GetSelfWinePress()
        CfUtils.FillText(self.TextAccumulateTxtNum, point)
        local pointId = DreamAdventuresMgr:GetActivityPointId()
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(pointId)
        CfUtils.FillImage(self.TextAccumulateImgicon, goodsVo.photoPath)
    elseif viewType == DreamAdventuresConstants.ScheduleRewardPopupType.SERVER then
        CfUtils.SetActive(self.ThatPerson, false)
        CfUtils.SetActive(self.FullServerProgress, true)
        CfUtils.SetActive(self.TextAccumulate, false)
        CfUtils.SetActive(self.TextSchedule, true)
        local allPercent = DreamAdventuresMgr:GetAllRewardsPercentage()
        CfUtils.FillText(self.TextScheduleTxtNum, string.format('%s%%', math.floor(allPercent * 1000) / 10))
    end
end

---领取奖励
---@param id number 奖励id, 为0领取全部
function DreamAdventuresProgressRewardsDialog:DrawRewards(id)
    local interface = nil
    local viewType = self:GetViewType()
    if viewType == DreamAdventuresConstants.ScheduleRewardPopupType.PERSONAL then
        interface = Interfaces.DreamAdventuresSelfDraw
    elseif viewType == DreamAdventuresConstants.ScheduleRewardPopupType.SERVER then
        interface = Interfaces.DreamAdventuresAllDraw
    end
    local activityId = DreamAdventuresMgr:GetActivityId()
    GameUtils.Request(interface, {activityUuid = activityId, rewardId = id}, Bind(self, self.DrawRewardsResponseHandler))
end
